package com.example.application_service.exception;import com.example.application_service.common.*;import jakarta.persistence.OptimisticLockException;import jakarta.servlet.http.HttpServletRequest;import org.slf4j.*;import org.springframework.dao.*;import org.springframework.http.*;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.method.annotation.*;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);@ExceptionHandler(ApiException.class)ResponseEntity<ApiErrorResponse> api(ApiException e,HttpServletRequest r){return out(e.status(),e.code(),e.getMessage(),List.of(),r);}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){var f=e.getBindingResult().getFieldErrors().stream().map(x->new FieldErrorResponse(x.getField(),x.getRejectedValue(),x.getDefaultMessage())).toList();return out(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Request validation failed",f,r);}@ExceptionHandler({HttpMessageNotReadableException.class,MethodArgumentTypeMismatchException.class,HandlerMethodValidationException.class,IllegalArgumentException.class})ResponseEntity<ApiErrorResponse> bad(Exception e,HttpServletRequest r){return out(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Request validation failed",List.of(),r);}@ExceptionHandler({OptimisticLockingFailureException.class,OptimisticLockException.class})ResponseEntity<ApiErrorResponse> lock(Exception e,HttpServletRequest r){return out(HttpStatus.CONFLICT,"OPTIMISTIC_LOCK_CONFLICT","Application was updated by another request",List.of(),r);}@ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<ApiErrorResponse> duplicate(Exception e,HttpServletRequest r){return out(HttpStatus.CONFLICT,"APPLICATION_ALREADY_EXISTS","You have already applied for this job",List.of(),r);}@ExceptionHandler(Exception.class)ResponseEntity<ApiErrorResponse> unexpected(Exception e,HttpServletRequest r){log.error("Unhandled application-service exception traceId={} type={}",trace(r),e.getClass().getName());return out(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_SERVER_ERROR","An unexpected error occurred",List.of(),r);}private ResponseEntity<ApiErrorResponse> out(HttpStatus s,String c,String m,List<FieldErrorResponse> f,HttpServletRequest r){String t=trace(r);return ResponseEntity.status(s).header(CorrelationIdFilter.HEADER,t).body(new ApiErrorResponse(c,m,f,t));}private String trace(HttpServletRequest r){Object v=r.getAttribute(CorrelationIdFilter.ATTRIBUTE);return v==null?UUID.randomUUID().toString():v.toString();}}
